<?php require_once '../config/database.php';require_once '../includes/functions.php';require_admin();$pageTitle='Orders';$active='orders';$statuses=['Placed','Processing','Shipped','Delivered','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id&&in_array($status,$statuses,true)){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);flash('success','Order status updated.');}go('orders.php');}$orders=$pdo->query("SELECT o.*,u.name user_name,u.email,p.name product_name FROM orders o JOIN users u ON u.id=o.user_id JOIN products p ON p.id=o.product_id ORDER BY o.id DESC")->fetchAll();$flash=flash_get();require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Sales</span><h1>Orders</h1><p>View orders and update their status.</p></div></div><?php if($flash):?><div class="alert success"><?=e($flash[1])?></div><?php endif;?><section class="admin-card"><div class="table-scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Qty</th><th>Total</th><th>Status</th><th>Date</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['user_name'])?><br><small><?=e($o['email'])?></small></td><td><?=e($o['product_name'])?></td><td><?=$o['quantity']?></td><td>₹<?=number_format((float)$o['total_amount'],2)?></td><td><span class="status <?=strtolower($o['status'])?>"><?=e($o['status'])?></span></td><td><?=e($o['created_at'])?></td><td><form method="post" style="display:flex;gap:6px"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" class="input" style="min-width:120px"><?php foreach($statuses as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn" style="padding:8px 10px">Save</button></form></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="8" class="empty-row">No orders yet.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';
